from PySide6.QtCore import Qt, QTimer, Signal, QObject, QSize
from PySide6.QtGui import QPixmap, QImage, QFont
from PySide6.QtWidgets import (
    QApplication, QMainWindow, QWidget, QFrame, QLabel, QPushButton, QLineEdit,
    QCheckBox, QVBoxLayout, QHBoxLayout, QGridLayout, QComboBox, QTextEdit,
    QStackedWidget, QMessageBox, QSizePolicy
)

# backend embedded below

APP_BG = "#03070C"
SIDE = "#06101A"
PANEL = "#081522"
PANEL2 = "#0B1B2A"
BORDER = "#173A55"
TEXT = "#F4F8FC"
MUTED = "#7F97AC"
BLUE = "#0A86F7"
CYAN = "#25D9FF"
GREEN = "#21E49A"
RED = "#FF4B62"
WAIT = "#A9C0D6"
LOGIN_ART_B64 = ''


def pixmap_from_b64(data: str) -> QPixmap:
    raw = base64.b64decode(data)
    img = QImage.fromData(raw)
    return QPixmap.fromImage(img)


class Bridge(QObject):
    login_ok = Signal(str)
    login_fail = Signal(str)


class ArtLabel(QLabel):
    def __init__(self, pixmap: QPixmap, parent=None, crop=True):
        super().__init__(parent)
        self._source = pixmap
        self._crop = crop
        self.setMinimumSize(10, 10)
        self.setStyleSheet("background:#050B13;")

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if self._source.isNull():
            return
        mode = Qt.AspectRatioMode.KeepAspectRatioByExpanding if self._crop else Qt.AspectRatioMode.KeepAspectRatio
        scaled = self._source.scaled(self.size(), mode, Qt.TransformationMode.SmoothTransformation)
        if self._crop:
            x = max(0, (scaled.width() - self.width()) // 2)
            y = max(0, (scaled.height() - self.height()) // 2)
            scaled = scaled.copy(x, y, min(self.width(), scaled.width()), min(self.height(), scaled.height()))
        self.setPixmap(scaled)


class NavButton(QPushButton):
    def __init__(self, text, active=False):
        super().__init__(text)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setMinimumHeight(44)
        self.setProperty("active", active)


class LoginPage(QWidget):
    def __init__(self, app_window):
        super().__init__()
        self.app_window = app_window
        self.bridge = Bridge()
        self.bridge.login_ok.connect(self._on_login_ok)
        self.bridge.login_fail.connect(self._on_login_fail)
        self._build()

    def _build(self):
        root = QHBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        # LEFT: artwork only, with real Qt branding overlays.
        visual = QFrame()
        visual.setObjectName("visual")
        visual_layout = QVBoxLayout(visual)
        visual_layout.setContentsMargins(0, 0, 0, 0)

        art = ArtLabel(pixmap_from_b64(LOGIN_ART_B64), crop=True)
        art.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        visual_layout.addWidget(art)

        brand = QFrame(visual)
        brand.setObjectName("brandOverlay")
        brand.setFixedWidth(470)
        brand_layout = QVBoxLayout(brand)
        brand_layout.setContentsMargins(26, 22, 26, 22)
        brand_layout.setSpacing(4)
        title = QLabel("BLACK ANGELS")
        title.setObjectName("heroTitle")
        sub = QLabel("S  E  N  T  I  N  E  L")
        sub.setObjectName("heroSub")
        desc = QLabel("Dino Storm Gate Monitoring  •  EU1")
        desc.setObjectName("muted")
        slogan = QLabel("PROTECT  •  MONITOR  •  STAY AHEAD")
        slogan.setObjectName("smallMuted")
        brand_layout.addWidget(title)
        brand_layout.addWidget(sub)
        brand_layout.addSpacing(8)
        brand_layout.addWidget(desc)
        brand_layout.addSpacing(14)
        brand_layout.addWidget(slogan)
        brand.move(52, 90)
        brand.raise_()

        root.addWidget(visual, 13)

        # RIGHT: real login surface, no image UI.
        right = QFrame()
        right.setObjectName("rightPane")
        right_layout = QVBoxLayout(right)
        right_layout.setContentsMargins(54, 58, 54, 58)
        right_layout.addStretch(1)

        card = QFrame()
        card.setObjectName("loginCard")
        card.setMinimumWidth(430)
        card.setMaximumWidth(560)
        card_layout = QVBoxLayout(card)
        card_layout.setContentsMargins(36, 34, 36, 34)
        card_layout.setSpacing(14)

        logo = QLabel("✦")
        logo.setObjectName("roundLogo")
        logo.setAlignment(Qt.AlignmentFlag.AlignCenter)
        logo.setFixedSize(58, 58)
        logo_row = QHBoxLayout()
        logo_row.addStretch(1)
        logo_row.addWidget(logo)
        logo_row.addStretch(1)
        card_layout.addLayout(logo_row)

        h1 = QLabel("BLACK ANGELS")
        h1.setObjectName("loginBrand")
        h1.setAlignment(Qt.AlignmentFlag.AlignCenter)
        card_layout.addWidget(h1)
        h2 = QLabel("S  E  N  T  I  N  E  L")
        h2.setObjectName("heroSub")
        h2.setAlignment(Qt.AlignmentFlag.AlignCenter)
        card_layout.addWidget(h2)
        card_layout.addSpacing(12)

        welcome = QLabel("Welcome Back")
        welcome.setObjectName("loginTitle")
        welcome.setAlignment(Qt.AlignmentFlag.AlignCenter)
        card_layout.addWidget(welcome)
        card_layout.addSpacing(10)

        self.user = QLineEdit()
        self.user.setPlaceholderText("Username")
        self.user.setObjectName("field")
        self.password = QLineEdit()
        self.password.setPlaceholderText("Password")
        self.password.setEchoMode(QLineEdit.EchoMode.Password)
        self.password.setObjectName("field")
        card_layout.addWidget(self.user)
        card_layout.addWidget(self.password)

        opts = QHBoxLayout()
        self.remember = QCheckBox("Remember me")
        self.save_password = QCheckBox("Save password")
        opts.addWidget(self.remember)
        opts.addStretch(1)
        opts.addWidget(self.save_password)
        card_layout.addLayout(opts)

        self.status = QLabel("●  Online • Secure connection")
        self.status.setObjectName("online")
        card_layout.addWidget(self.status)

        self.login_btn = QPushButton("LOG IN   →")
        self.login_btn.setObjectName("primary")
        self.login_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.login_btn.clicked.connect(self.submit)
        card_layout.addWidget(self.login_btn)

        stronger = QLabel("PROTECT  •  MONITOR  •  STAY AHEAD")
        stronger.setObjectName("smallMuted")
        stronger.setAlignment(Qt.AlignmentFlag.AlignCenter)
        card_layout.addWidget(stronger)

        saved = backend.load_admin_login_prefs()
        if saved.get("remember_username"):
            self.user.setText(saved.get("username", ""))
            self.remember.setChecked(True)
        if saved.get("remember_password"):
            self.password.setText(saved.get("password", ""))
            self.save_password.setChecked(True)

        wrap = QHBoxLayout()
        wrap.addStretch(1)
        wrap.addWidget(card)
        wrap.addStretch(1)
        right_layout.addLayout(wrap)
        right_layout.addStretch(1)
        root.addWidget(right, 7)

        self.password.returnPressed.connect(self.submit)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        # Keep overlay in a visually stable location on the artwork.
        visual = self.layout().itemAt(0).widget()
        brand = visual.findChild(QFrame, "brandOverlay")
        if brand:
            brand.move(52, max(60, visual.height() // 3 - 70))

    def submit(self):
        username = self.user.text().strip()
        password = self.password.text()
        if not username or not password:
            self.status.setText("Enter username and password")
            self.status.setStyleSheet(f"color:{RED};")
            return
        self.login_btn.setEnabled(False)
        self.status.setText("Signing in…")
        self.status.setStyleSheet(f"color:{CYAN};")

        def worker():
            try:
                backend.perform_login(username, password)
                backend.save_admin_login_prefs(
                    backend.AUTH_SERVER_URL, username, password,
                    self.remember.isChecked(), self.save_password.isChecked()
                )
                backend.reporter_name = username
                self.bridge.login_ok.emit(username)
            except Exception as e:
                self.bridge.login_fail.emit(str(e))

        threading.Thread(target=worker, daemon=True).start()

    def _on_login_ok(self, username):
        self.status.setText("Signed in successfully")
        self.status.setStyleSheet(f"color:{GREEN};")
        self.app_window.dashboard.set_user(username)
        self.app_window.pages.setCurrentWidget(self.app_window.dashboard)
        self.login_btn.setEnabled(True)
        try:
            backend.auth_stop_event.clear()
            threading.Thread(target=backend._heartbeat_loop, daemon=True).start()
        except Exception:
            pass

    def _on_login_fail(self, error):
        self.status.setText(f"Sign-in failed • {error}")
        self.status.setStyleSheet(f"color:{RED};")
        self.login_btn.setEnabled(True)


class GateCard(QFrame):
    def __init__(self, gate_name, thumb_b64, rename_callback):
        super().__init__()
        self.gate_name = gate_name
        self.setObjectName("card")
        layout = QHBoxLayout(self)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(10)

        img = QLabel()
        img.setFixedSize(66, 76)
        pm = pixmap_from_b64(thumb_b64).scaled(66,76,Qt.AspectRatioMode.KeepAspectRatioByExpanding,Qt.TransformationMode.SmoothTransformation)
        img.setPixmap(pm)
        img.setScaledContents(True)
        img.setObjectName("thumb")
        layout.addWidget(img)

        center = QVBoxLayout()
        self.name = QLabel(gate_name)
        self.name.setObjectName("gateName")
        self.state = QLabel("●  WAITING")
        self.state.setStyleSheet(f"color:{WAIT}; font-weight:700;")
        self.last = QLabel("Last update: waiting for scan")
        self.last.setObjectName("smallMuted")
        center.addWidget(self.name)
        center.addWidget(self.state)
        center.addWidget(self.last)
        center.addStretch(1)
        layout.addLayout(center, 1)

        gear = QPushButton("⚙")
        gear.setObjectName("iconButton")
        gear.setFixedSize(34,34)
        gear.clicked.connect(lambda: rename_callback(self.gate_name))
        layout.addWidget(gear, 0, Qt.AlignmentFlag.AlignTop)

    def refresh(self):
        self.name.setText(backend.display_gate_name(self.gate_name))
        state = str(backend.gate_states.get(self.gate_name, "WAITING")).upper()
        if "ATTACK" in state or "ALERT" in state:
            label, color = "●  ALERT", RED
        elif "DV" in state:
            label, color = "●  DV", CYAN
        elif "SAFE" in state or "CLEAR" in state:
            label, color = "●  CLEAR", GREEN
        else:
            label, color = "●  WAITING", WAIT
        self.state.setText(label)
        self.state.setStyleSheet(f"color:{color}; font-weight:700;")


